#include "cliptiq/lan.hpp"
#include <iostream>
#include "sqlite3.h"
#include <filesystem>
#include <chrono>
#include <stdexcept>
using namespace cliptiq;
#define CHECK(x) if(!(x))throw std::runtime_error(#x)
template<class T>T take(Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(r.value());}
void ok(Result<void> r){if(!r)throw std::runtime_error(r.error().message);}
int main(){try{
 auto s=take(open_store(":memory:"));auto c=take(lan::load_config(s));CHECK(!c.device_id.empty());auto stale=c;c.device_name="Local";ok(lan::save_config(s,c));CHECK(!lan::save_config(s,stale));c=take(lan::load_config(s));lan::Peer p;p.id=lan::new_id();p.name="Desk";p.host="127.0.0.1";p.secret_ref="secret";p.auth_id=std::string(64,'a');c.peers.push_back(p);ok(lan::save_config(s,c));auto remote=lan::new_id();ok(lan::bind_peer_identity(s,p.id,remote));CHECK(!lan::bind_peer_identity(s,p.id,lan::new_id()));CHECK(!lan::bind_peer_identity(s,p.id,c.device_id));
 lan::Event e{remote,lan::new_id(),1,1,{{0,"portable","text/plain",CanonicalKind::Text,{'h','i'}}}};auto wire=take(lan::encode_event(e));CHECK(take(lan::decode_event(wire)).event_id==e.event_id);wire.push_back(0);CHECK(!lan::decode_event(wire));auto bad=e;bad.representations[0].data={0xc0,0x80};CHECK(!lan::encode_event(bad));bad=e;bad.representations[0].native_type="text/html";CHECK(!lan::encode_event(bad));
 auto a=take(lan::accept_event(s,p.id,e,{},2));CHECK(a.entry_id);CHECK(take(load_snapshot(s,*a.entry_id)).representations[0].platform!="portable");CHECK(take(lan::entry_origin(s,*a.entry_id))=="Desk");CHECK(take(lan::accept_event(s,p.id,e,{},3)).duplicate);e.event_id=lan::new_id();CHECK(take(lan::accept_event(s,p.id,e,{},4)).duplicate);e.sequence=2;HistoryPolicy hp;hp.allow_duplicates=false;auto b=take(lan::accept_event(s,p.id,e,hp,5));CHECK(b.entry_id&&b.entry_id!=a.entry_id);CHECK(take(list_history(s)).size()==2);ok(erase_history(s,*a.entry_id));CHECK(!take(lan::is_remote_entry(s,*a.entry_id)));CHECK(take(lan::accept_event(s,p.id,e,{},6)).duplicate);
 // Failure after history insertion must roll back all provenance and replay state.
 e.sequence=3;e.event_id=lan::new_id();CHECK(sqlite3_exec(s.connection(),"CREATE TRIGGER reject_origin BEFORE INSERT ON lan_entry_origins BEGIN SELECT RAISE(ABORT,'test failure'); END",nullptr,nullptr,nullptr)==SQLITE_OK);CHECK(!lan::accept_event(s,p.id,e,{},7));CHECK(take(list_history(s)).size()==1);CHECK(sqlite3_exec(s.connection(),"DROP TRIGGER reject_origin",nullptr,nullptr,nullptr)==SQLITE_OK);CHECK(take(lan::accept_event(s,p.id,e,{},8)).entry_id);
 auto secondConfig=take(lan::load_config(s));auto peer2=p;peer2.id=lan::new_id();peer2.name="Laptop";peer2.secret_ref="secret2";peer2.auth_id=std::string(64,'c');secondConfig.peers.push_back(peer2);ok(lan::save_config(s,secondConfig));auto remote2=lan::new_id();ok(lan::bind_peer_identity(s,peer2.id,remote2));auto from2=e;from2.origin_device_id=remote2;from2.event_id=lan::new_id();from2.sequence=1;auto arrival2=take(lan::accept_event(s,peer2.id,from2,{},9));CHECK(arrival2.entry_id);CHECK(take(lan::entry_origin(s,*arrival2.entry_id))=="Laptop");CHECK(take(lan::entry_origin(s,*b.entry_id))=="Desk");
 auto nativeLocal=take(lan::native_snapshot(e,CapturePlatform::Windows));HistoryPolicy localPolicy;auto local1=take(ingest(s,nativeLocal,localPolicy,10));CHECK(local1);auto local2=take(ingest(s,nativeLocal,localPolicy,11));CHECK(local2==local1);CHECK(!take(lan::is_remote_entry(s,*local1)));CHECK(take(lan::entry_origin(s,*b.entry_id))=="Desk");
 auto bound=take(lan::load_config(s));ok(lan::bind_peer_identity(s,p.id,remote));CHECK(take(lan::load_config(s)).revision==bound.revision);auto rotate=bound;rotate.peers[0].remote_device_id.clear();CHECK(!lan::save_config(s,rotate));rotate.peers[0].secret_ref="rotated";rotate.peers[0].auth_id=std::string(64,'b');ok(lan::save_config(s,rotate));CHECK(!lan::save_config(s,bound));CHECK(!lan::accept_event(s,p.id,e,{},9));
 for(auto platform:{CapturePlatform::Windows,CapturePlatform::MacOS,CapturePlatform::X11,CapturePlatform::Wayland}){auto native=take(lan::native_snapshot(e,platform));CHECK(native.flags.remote==Flag::No);auto portable=take(lan::portable_snapshot(native,c));CHECK(portable[0].data==e.representations[0].data);}
 auto image=e;image.representations={{0,"portable","image/png",CanonicalKind::Image,Bytes(33)}};CHECK(!lan::encode_event(image));for(size_t n=0;n+1<wire.size();++n){Bytes truncated(wire.begin(),wire.begin()+n);CHECK(!lan::decode_event(truncated));}
 // A v2 database migrates without losing existing history; settings CAS spans connections.
 auto directory=std::filesystem::temp_directory_path()/("cliptiq-lan-"+lan::new_id());std::filesystem::create_directories(directory);auto path=(directory/"history.db").u8string();{auto db=take(open_store(path));ClipboardSnapshot local;local.representations={{0,"test","text/plain",CanonicalKind::Text,{'x'}}};CHECK(take(ingest(db,local,{},1)));CHECK(sqlite3_exec(db.connection(),"DROP TABLE lan_entry_origins;DROP TABLE lan_seen;DROP TABLE lan_origins;DROP TABLE lan_state;PRAGMA user_version=2",nullptr,nullptr,nullptr)==SQLITE_OK);}{auto first=take(open_store(path));auto second=take(open_store(path));CHECK(take(list_history(first)).size()==1);auto one=take(lan::load_config(first));auto two=take(lan::load_config(second));one.device_name="First";ok(lan::save_config(first,one));two.device_name="Second";CHECK(!lan::save_config(second,two));auto ev=take(lan::make_event(first,e.representations,1));auto next=take(lan::make_event(second,e.representations,2));CHECK(next.sequence==ev.sequence+1);}{auto db=take(open_store(path));CHECK(take(lan::make_event(db,e.representations,3)).sequence==3);}std::error_code ignored;std::filesystem::remove_all(directory,ignored);
 // Portable conversion must preserve the complete clipboard, not search-index text.
 for(auto encoding:{TextEncoding::Utf16Le,TextEncoding::Utf16Be}){std::string original=" \t\r\n"+std::string(2*1024*1024,'q')+"\n\t ";Bytes wide;auto unit=[&](uint16_t n){if(encoding==TextEncoding::Utf16Le){wide.push_back(n&255);wide.push_back(n>>8);}else{wide.push_back(n>>8);wide.push_back(n&255);}};unit(0xfeff);for(auto ch:original)unit(uint8_t(ch));unit(0);ClipboardSnapshot capture;capture.representations={{0,"windows","CF_UNICODETEXT",CanonicalKind::Text,wide,encoding}};auto full=take(lan::portable_snapshot(capture,c));CHECK(std::string(full[0].data.begin(),full[0].data.end())==original);capture.representations[0].data=encoding==TextEncoding::Utf16Le?Bytes{0,0xd8}:Bytes{0xd8,0};CHECK(!lan::portable_snapshot(capture,c));capture.representations[0].data=encoding==TextEncoding::Utf16Le?Bytes{0,0xdc}:Bytes{0xdc,0};CHECK(!lan::portable_snapshot(capture,c));}
 auto fileUrl=e;fileUrl.representations={{0,"portable","text/uri-list",CanonicalKind::Url,{'F','I','L','E',':','/','/','/','x'}}};CHECK(!lan::encode_event(fileUrl));auto multi=e;multi.representations[0].item_index=1;CHECK(!lan::native_snapshot(multi,CapturePlatform::Windows));
 ClipboardSnapshot terminated;terminated.representations={{0,"macos","public.utf8-plain-text",CanonicalKind::Text,{' ','a',' ',0}}};CHECK(take(lan::portable_snapshot(terminated,c))[0].data==Bytes({' ','a',' '}));terminated.representations[0].data={'a',0,'b',0};CHECK(!lan::portable_snapshot(terminated,c));
 ClipboardSnapshot hidden;hidden.flags.concealed=Flag::Yes;hidden.representations=e.representations;CHECK(!lan::portable_snapshot(hidden,c));std::cout<<"PASS LAN protocol/config/provenance\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
